<script setup lang="ts">
import { t as uiText } from '@/locales'

import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue'
import dayjs from 'dayjs'
import {useUserStore} from '@/stores/user'
import {newRequestId} from '@/api/modules/partner'
import {sampleIdentity,sampleIdentityBulkAction} from '@/api/modules/sampleManagement'
import type {SampleIdentity,SampleLoan} from '@/types/sampleManagement'
import {useSampleSubmission} from './useSampleSubmission'
const props=defineProps<{action:'loan'|'return';samples:SampleIdentity[]}>(),emit=defineEmits<{close:[];saved:[]}>(),user=useUserStore(),auth=user.token
const {busy,error,unknown,submit}=useSampleSubmission(`bulk:${props.action}:${props.samples.map(s=>s.sampleIdentityId).sort((a,b)=>a-b).join(',')}`)
interface Row {sample:SampleIdentity;qty?:number;location:string;loan?:SampleLoan;damaged:number}
const loading=ref(true),rows=ref<Row[]>([]),uniform=ref('1'),form=reactive({date:dayjs().format('YYYY-MM-DD'),person:'',due:'',note:''}),requestId=newRequestId()
let disposed=false
const title=computed(()=>props.action==='loan'?'批量借出样品':'批量归还样品')
const places=(row:Row)=>(row.sample.positions||row.sample.balances.positions||[]).filter(p=>props.action==='return'||p.available>0)
const maximum=(row:Row)=>props.action==='return'?row.loan!.outstanding:places(row).find(p=>p.name===row.location)?.available||0
onMounted(async()=>{try{const details=await Promise.all(props.samples.map(s=>sampleIdentity(s.sampleIdentityId)));if(disposed||auth!==user.token)return;rows.value=details.flatMap(sample=>props.action==='return'?(sample.loans||sample.balances.loans||[]).filter(l=>l.outstanding>0).map(loan=>({sample,loan,qty:undefined,damaged:0,location:loan.location||''})):[{sample,qty:undefined,damaged:0,location:(sample.positions||sample.balances.positions||[]).filter(p=>p.available>0).length===1?(sample.positions||sample.balances.positions||[]).find(p=>p.available>0)!.name:''}]);if(unknown.value)error.value='上次批量办理的保存结果待核对，请使用原提交核对结果，避免重复记录。';else if(!rows.value.length)error.value='所选样品没有待归还记录。'}catch(e){error.value=e instanceof Error?e.message:'读取所选样品失败，请关闭后重试'}finally{loading.value=false}})
function applyQuantity(){if(!/^[1-9]\d*$/.test(uniform.value)||!Number.isSafeInteger(Number(uniform.value))){error.value='请输入正整数数量';return}for(const row of rows.value)row.qty=Number(uniform.value);error.value=''}
function close(){if(!busy.value&&!unknown.value)emit('close')}
async function save(){if(loading.value||(!rows.value.length&&!unknown.value))return;if(!unknown.value){if(!form.date||(props.action==='loan'&&(!form.person.trim()||!form.due))){error.value='请填写实际日期、借用人和预计归还日期';return}const invalid=rows.value.find(row=>!Number.isSafeInteger(row.qty)||Number(row.qty)<0||Number(row.qty)>maximum(row)||(Number(row.qty)>0&&!row.location.trim())||row.damaged>Number(row.qty));if(invalid){error.value=invalid.sample.sampleCode+'：请核对位置、数量及损坏数，数量不能超过可用／待还数量';return}if(!rows.value.some(r=>Number(r.qty)>0)){error.value='请至少填写一项本次实际数量；不办理的行填0';return}}
 const result=await submit(()=>{const items=[...new Set(rows.value.filter(r=>Number(r.qty)>0).map(r=>r.sample.sampleIdentityId))].map(id=>{const matches=rows.value.filter(r=>r.sample.sampleIdentityId===id&&Number(r.qty)>0),first=matches[0]!;return props.action==='loan'?{sampleIdentityId:id,version:first.sample.version,qty:first.qty,location:first.location.trim()}:{sampleIdentityId:id,version:first.sample.version,allocations:matches.map(r=>({batchId:r.loan!.batchId,loanId:r.loan!.id,qty:r.qty,location:r.location.trim(),damaged:r.damaged}))}});return{requestId,date:form.date,person:form.person.trim(),due:form.due,note:form.note,items}},payload=>sampleIdentityBulkAction(props.action,payload));if(result&&!disposed&&auth===user.token)emit('saved')}
watch(()=>user.token,()=>emit('close'));onBeforeUnmount(()=>{disposed=true})
</script>
<template><el-dialog class="sample-batch-dialog" :model-value="true" :title="title" width="min(960px,96vw)" append-to-body :close-on-click-modal="false" :before-close="close"><div class="batch-content" v-loading="loading"><el-form label-position="top" :disabled="busy||unknown||loading"><div class="common-fields"><el-form-item :label='uiText("本次实际日期 *")'><el-date-picker v-model="form.date" value-format="YYYY-MM-DD"/></el-form-item><template v-if="action==='loan'"><el-form-item :label='uiText("借用人／接收人 *")'><el-input v-model="form.person" :aria-label='uiText("批量借用人")'/></el-form-item><el-form-item :label='uiText("预计归还日期 *")'><el-date-picker v-model="form.due" value-format="YYYY-MM-DD" :aria-label='uiText("批量预计归还日期")'/></el-form-item></template></div><div class="uniform"><el-input v-model="uniform" inputmode="numeric" :placeholder='uiText("统一数量")' :aria-label='uiText("批量统一数量")'/><el-button @click="applyQuantity">{{ uiText("应用到全部 ") }}{{rows.length}}{{ uiText(" 项") }}</el-button><small>{{ uiText("可逐行调整；本次不办理填0") }}</small></div><div class="batch-rows"><article v-for="(row,index) in rows" :key="row.sample.sampleIdentityId+':'+(row.loan?.id||'loan')"><strong>{{row.sample.sampleCode}} · {{row.sample.productName||row.sample.name}}<small>{{row.sample.phoneName||row.sample.specName}} · {{row.sample.colorName}}<template v-if="row.loan"> · {{row.loan.person}}{{ uiText(" · 待还 ") }}{{row.loan.outstanding}}</template></small></strong><label>{{action==='loan'?uiText('取出位置'):uiText('归还位置')}} *<el-select v-model="row.location" filterable :allow-create="action==='return'" default-first-option :aria-label="uiText('本次位置 ')+index"><el-option v-for="p in places(row)" :key="p.name" :value="p.name" :label="p.name+uiText(' · 可用 ')+p.available"/><el-option v-if="row.loan?.location&&!places(row).some(p=>p.name===row.loan?.location)" :value="row.loan.location" :label="row.loan.location"/></el-select></label><label>{{action==='loan'?uiText('借出数量'):uiText('归还数量')}} *<el-input-number v-model="row.qty" :min="0" :max="maximum(row)" :precision="0" :aria-label="uiText('本次数量 ')+index"/></label><label v-if="action==='return'">{{ uiText("其中损坏") }}<el-input-number v-model="row.damaged" :min="0" :max="row.qty||0" :precision="0" :aria-label="uiText('本次损坏 ')+index"/></label></article></div><el-form-item :label='uiText("备注（选填）")'><el-input v-model="form.note" type="textarea" autosize/></el-form-item></el-form><el-alert v-if="error" :title="error" type="error" :closable="false"/></div><template #footer><el-button :disabled="busy||unknown" @click="close">{{ uiText("取消") }}</el-button><el-button type="primary" :loading="busy" :disabled="loading||(!rows.length&&!unknown)" @click="save">{{unknown?uiText('核对本次保存结果'):uiText('确认本次')+(action==='loan'?uiText('借出'):uiText('归还'))}}</el-button></template></el-dialog></template>
<style scoped>.batch-content{min-width:0;font-size:12px}.common-fields,.uniform{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.common-fields>*{flex:1;min-width:160px}.uniform{margin-bottom:12px}.uniform small{color:#75869a}.batch-rows article{display:flex;gap:10px;flex-wrap:wrap;align-items:end;border-block-start:1px solid #e2e9f1;padding:10px 0}.batch-rows strong{flex-basis:100%;overflow-wrap:anywhere}.batch-rows small{display:block;font-weight:400;color:#70839a}.batch-rows label{display:flex;flex-direction:column;gap:4px;flex:1;min-width:145px}.batch-rows :deep(.el-input-number),.batch-rows :deep(.el-select){width:100%}.batch-content :deep(.el-form-item__label){font-size:12px}:global(.sample-batch-dialog){display:flex;flex-direction:column;max-height:calc(100dvh - 40px);margin-block:20px;overflow:hidden}:global(.sample-batch-dialog>.el-dialog__body){min-height:0;overflow:auto}:global(.sample-batch-dialog>.el-dialog__header),:global(.sample-batch-dialog>.el-dialog__footer){flex:none}</style>
